"use client"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import type { Recipient } from "../schema"

function initials(name: string) {
  return name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase()
}

// CAND-001 (Avatar gap) — initials circle, no image support needed here.
function RecipientAvatar({ name }: { name: string }) {
  return (
    <div
      aria-hidden="true"
      style={{
        width: "var(--atlas-spacing-10)",
        height: "var(--atlas-spacing-10)",
        borderRadius: "var(--atlas-radius-full)",
        backgroundColor: "var(--atlas-primary-subtle)",
        color: "var(--atlas-primary)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontSize: "var(--atlas-font-size-sm)",
        fontWeight: "var(--atlas-font-weight-semibold)",
        flexShrink: 0,
      }}
    >
      {initials(name)}
    </div>
  )
}

// CAND-002 (ListRow gap) — leading avatar + title/subtitle + trailing meta, selectable.
export function RecipientRow({
  recipient,
  onSelect,
}: {
  recipient: Recipient
  onSelect: () => void
}) {
  return (
    <Card variant="outlined" size="sm" interactive onClick={onSelect}>
      <CardContent>
        <div style={{ display: "flex", alignItems: "center", gap: "var(--atlas-spacing-3)" }}>
          <RecipientAvatar name={recipient.name} />
          <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-0_5)", flex: 1, minWidth: 0 }}>
            <span
              style={{
                fontSize: "var(--atlas-text-body)",
                fontWeight: "var(--atlas-font-weight-medium)",
                color: "var(--atlas-foreground)",
              }}
            >
              {recipient.name}
            </span>
            <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>
              {recipient.maskedAccount}
            </span>
          </div>
          <Badge variant="secondary" size="sm">
            {recipient.currency}
          </Badge>
        </div>
      </CardContent>
    </Card>
  )
}

