"use client"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RECENT_RECIPIENTS, type SendMoneyStepProps } from "../schema"
import { RecipientRow } from "./_parts"

export function Recipient({ data, patch, next }: SendMoneyStepProps) {
  const filtered = RECENT_RECIPIENTS.filter((r) =>
    r.name.toLowerCase().includes(data.search.trim().toLowerCase())
  )

  const select = (id: string, currency: string) => {
    patch({ recipientId: id, receiveCurrency: currency })
    next()
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-4)", paddingInline: "var(--atlas-spacing-4)" }}>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <Label htmlFor="recipient-search">Search recipients</Label>
        <Input
          id="recipient-search"
          size="md"
          placeholder="Name or account"
          value={data.search}
          onChange={(e) => patch({ search: e.target.value })}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <span
          style={{
            fontSize: "var(--atlas-text-caption)",
            fontWeight: "var(--atlas-font-weight-medium)",
            color: "var(--atlas-foreground-muted)",
          }}
        >
          Recent recipients
        </span>
        <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
          {filtered.map((r) => (
            <RecipientRow key={r.id} recipient={r} onSelect={() => select(r.id, r.currency)} />
          ))}
          {filtered.length === 0 && (
            <span style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-subtle)" }}>
              No recipients match "{data.search}".
            </span>
          )}
        </div>
      </div>
    </div>
  )
}

